$('bkReset').onclick=()=>confirmBox('Réinitialiser la démonstration','<p>Toutes les données saisies sont remplacées par les données d’exemple. Les mots de passe redeviennent « '+DEFAULT_PW+' ». Le journal d’audit est conservé. Un point de restauration de l’état actuel est créé avant : on peut revenir en arrière.</p>',()=>applyKeys({},'Réinitialisation de la démonstration'),'Tout réinitialiser');
